// taskManager.js 수정
import { MCPClient } from './mcpClient.js';

class TaskManager {
  constructor() {
    this.mcpClient = new MCPClient('shrimp-task-manager');
  }

  async getPendingTasks() {
    const result = await this.mcpClient.callTool('mcp__shrimp-task-manager__list_tasks', { status: 'pending' });
    return result.tasks || [];
  }

  async executeTask(taskId) {
    return await this.mcpClient.callTool('mcp__shrimp-task-manager__execute_task', { taskId });
  }

  async verifyTask(taskId, summary, score) {
    return await this.mcpClient.callTool('mcp__shrimp-task-manager__verify_task', { taskId, summary, score });
  }
}

